package com.chessapp.ui.board

import androidx.compose.ui.geometry.Offset
import androidx.compose.ui.graphics.Color
import androidx.compose.ui.graphics.Path
import androidx.compose.ui.graphics.StrokeCap
import androidx.compose.ui.graphics.StrokeJoin
import androidx.compose.ui.graphics.drawscope.DrawScope
import androidx.compose.ui.graphics.drawscope.Fill
import androidx.compose.ui.graphics.drawscope.Stroke
import androidx.compose.ui.graphics.drawscope.translate
import com.chessapp.domain.model.PieceType
import com.chessapp.domain.model.Color as PieceColor

/**
 * Cburnett chess pieces (Wikipedia/Lichess set), (C) Colin M.L. Burnett,
 * GPLv2+ — see THIRD_PARTY_LICENSES.md. AUTHENTIC PER-COLOR geometry: black
 * pieces carry their designed light inner detail so they read on any square.
 *
 * Geometry ships as STRING constants parsed once at class load: constant-pool
 * data has no method-bytecode footprint, unlike floatArrayOf literals whose
 * aggregated initializers exceeded the JVM 64KB method limit and crashed the
 * Kotlin daemon. role: 0=body(fill+outline) 1=detail stroke 2=contrast fill.
 */
object PieceRenderer {

    private const val VIEW = 45f

    private class Part(val role: Int, val closed: Boolean, data: String) {
        val pts: FloatArray = run {
            val toks = data.split(' ')
            val a = FloatArray(toks.size * 2)
            var i = 0
            for (t in toks) {
                val c = t.indexOf(',')
                a[i++] = t.substring(0, c).toFloat()
                a[i++] = t.substring(c + 1).toFloat()
            }
            a
        }
    }

    fun draw(
        scope: DrawScope,
        type: PieceType,
        color: PieceColor,
        topLeft: Offset,
        cell: Float,
        fillBrush: androidx.compose.ui.graphics.Brush? = null,
        lineOverride: Color? = null
    ) {
        val fill = if (color == PieceColor.WHITE) Color(0xFFF7F3E8) else Color(0xFF2B2B28)
        val line = lineOverride ?: if (color == PieceColor.WHITE) Color(0xFF1A1A17) else Color(0xFFE8E2D2)
        // VERBATIM cburnett: black pieces carry a DARK body outline; their light
        // elements are INNER details only. This is exactly why the reference
        // apps' black pieces read identically on light and dark squares.
        val bodyLine = if (color == PieceColor.WHITE) line
                       else (lineOverride ?: Color(0xFF1A1A17))
        val pad = cell * 0.06f
        val s = (cell - pad * 2) / VIEW
        val stroke = Stroke(width = 1.5f * s, cap = StrokeCap.Round, join = StrokeJoin.Round)

        scope.translate(topLeft.x + pad, topLeft.y + pad) {
            for (part in partsFor(type, color)) {
                val path = Path().apply {
                    val p = part.pts
                    moveTo(p[0] * s, p[1] * s)
                    var i = 2
                    while (i < p.size) { lineTo(p[i] * s, p[i + 1] * s); i += 2 }
                    if (part.closed) close()
                }
                when (part.role) {
                    0 -> {
                        if (fillBrush != null) drawPath(path, fillBrush, style = Fill)
                        else drawPath(path, fill, style = Fill)
                        drawPath(path, bodyLine, style = stroke)
                    }
                    1 -> drawPath(path, line, style = stroke)
                    2 -> drawPath(path, line, style = Fill)
                }
            }
        }
    }

    private fun partsFor(type: PieceType, color: PieceColor): List<Part> =
        if (color == PieceColor.WHITE) when (type) {
            PieceType.PAWN -> W_PAWN; PieceType.ROOK -> W_ROOK
            PieceType.KNIGHT -> W_KNIGHT; PieceType.BISHOP -> W_BISHOP
            PieceType.QUEEN -> W_QUEEN; PieceType.KING -> W_KING
        } else when (type) {
            PieceType.PAWN -> B_PAWN; PieceType.ROOK -> B_ROOK
            PieceType.KNIGHT -> B_KNIGHT; PieceType.BISHOP -> B_BISHOP
            PieceType.QUEEN -> B_QUEEN; PieceType.KING -> B_KING
        }

